const event = $json;
const entry = event.entry?.[0]?.changes?.[0]?.value || event.value || {};
const messages = entry.messages || event.messages || [];
const message = messages[0] || {};
const contacts = entry.contacts || event.contacts || [];
const contact = contacts[0] || {};
const from = message.from || contact.wa_id || event.from || '';
const chatId = from || '';
const profileName = contact.profile?.name || '';
const timestamp = Number(message.timestamp || Math.floor(Date.now() / 1000));

return {
  json: {
    rawEvent: event,
    entry,
    message,
    contact,
    from,
    chatId,
    profileName,
    timestamp,
    messageId: message.id || null,
    messageType: message.type || ''
  }
};

const data = $input.first().json;
const interactive = data.message?.interactive || {};
const button = interactive.button_reply || interactive.list_reply || {};
const id = button.id || button.payload || '';
const title = button.title || button.description || '';

return {
  json: {
    from: data.from,
    chatId: data.chatId,
    text: title || id,
    type: 'callback',
    routerCategory: id,
    timestamp: data.timestamp,
    messageId: data.messageId,
    buttonReplyId: id || null,
    rawEvent: data.rawEvent
  }
};

const data = $input.first().json;
