const data = $input.first().json;
const message = data.message || {};
const audio = message.audio || message.voice || {};
const mediaId = audio.id;

if (!mediaId) {
  return [{
    json: {
      ...data,
      voiceFileId: '',
      voiceMimeType: audio.mime_type || 'audio/ogg'
    }
  }];
}

const meta = await this.helpers.requestWithAuthentication.call(this, 'whatsAppApi', {
  method: 'GET',
  url: `https://graph.facebook.com/v19.0/${mediaId}`,
  json: true,
});

const fileBuffer = await this.helpers.requestWithAuthentication.call(this, 'whatsAppApi', {
  method: 'GET',
  url: meta.url,
  encoding: null,
  json: false,
});

const mimeType = audio.mime_type || meta.mime_type || 'audio/ogg';

return [{
  json: {
    ...data,
    voiceFileId: mediaId,
    voiceMimeType: mimeType
  },
  binary: {
    data: {
      data: Buffer.from(fileBuffer),
      mimeType,
      fileName: `${mediaId}.ogg`
    }
  }
}];

const transcription = $input.first().json.content?.parts?.[0]?.text || '';
