const input = $input.first().json;
const messageData = $('Merge All Types').first().json;

const lastStates = Array.isArray(input) ? input : [input];
const last = lastStates[0] || {};

const text = (messageData.text || '').toLowerCase().trim();
const type = messageData.type || 'text';
const callbackData = messageData.routerCategory || '';

const menuCommands = ['/start', '/menu', '/exit', 'menu', 'ir_menu', 'inicio', 'hola', 'exit'];
const showMenu = menuCommands.includes(text);

const categories = ['fichajes', 'vacaciones', 'ausencias', 'valoracion', 'presupuesto', 'factura', 'contactos', 'visita', 'facturacion'];
const isMainMenuClick = type === 'callback' && categories.includes(callbackData);
const isSubmenuAction = type === 'callback' && (callbackData.includes('_consultar') || callbackData.includes('_crear'));

return {
  json: {
    ...messageData,
    showMenu,
    isMainMenuClick,
    isSubmenuAction,
    currentState: last.state_json || null,
    previousStates: lastStates
  }
};

