const data = $input.first().json;
const callbackData = data.routerCategory || '';

const parts = callbackData.split('_');
let action = '';
if (parts.length === 2) {
  action = parts[1];
}

const category = data.currentState;

const payload = {
  from: data.from,
  chat_id: data.chatId,
  text: data.text || callbackData,
  original_type: data.originalType || 'text',
  platform: 'whatsapp',
  timestamp: data.timestamp,
  message_id: data.messageId,
  callback_data: callbackData,
  action
};

if (data.hasImage) {
  payload.has_image = true;
  payload.photo_file_id = data.photoFileId;
  payload.image_base64 = data.imageBase64;
  payload.image_mime_type = data.imageMimeType;
}

if (data.hasDocument) {
  payload.has_document = true;
  payload.document_file_id = data.documentFileId;
  payload.filename = data.filename;
  payload.mime_type = data.mimeType;
  payload.document_base64 = data.documentBase64;
}

if (data.hasLocation) {
  payload.has_location = true;
  payload.latitude = data.latitude;
  payload.longitude = data.longitude;
}

if (data.voiceFileId) {
  payload.voice_file_id = data.voiceFileId;
  payload.voice_base64 = data.voiceBase64;
  payload.voice_mime_type = data.voiceMimeType;
}

const endpoints = {
  fichajes: 'https://automatizacion.plataformasnetwork.com/webhook/fichajes_optimiza',
  vacaciones: 'https://automatizacion.plataformasnetwork.com/webhook/vacaciones_optimiza',
  ausencias: 'https://automatizacion.plataformasnetwork.com/webhook/ausencias_optimiza',
  valoracion: 'https://automatizacion.plataformasnetwork.com/webhook/crear_valoracion_optimiza',
  presupuesto: 'https://automatizacion.plataformasnetwork.com/webhook/presupuestos_optimiza',
  factura: 'https://automatizacion.plataformasnetwork.com/webhook/facturas_optimiza',
  contactos: 'https://automatizacion.plataformasnetwork.com/webhook/contactos_optimiza',
  visita: 'https://automatizacion.plataformasnetwork.com/webhook/visita_optimiza',
  facturacion: 'https://automatizacion.plataformasnetwork.com/webhook/facturacion_optimiza'
};

const endpoint = endpoints[category];

if (!endpoint) {
  throw new Error(`Unknown category: ${category}`);
}

return {
  json: {
    endpoint,
    category,
    action,
    payload,
    chatId: data.chatId,
    callbackData
  }
};
